import { Component, ComponentInterface, Element, h, Host, Prop } from '@stencil/core';
import { NavigationSizes } from '../../../../../../types';

/**
 * @slot default - here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-burger-menu-category',
  styleUrl: 'burger-menu-category.scss',
  shadow: true,
})
export class BurgerMenuCategory implements ComponentInterface {
  @Element() host: HTMLElement;

  /**
   * hidden attribute
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  componentDidLoad() {
    this.host.style.setProperty('--nesting-level', this.getNestingLevel().level.toString());
    this.host.style.setProperty('--icon-count', this.getNestingLevel().icons.toString());
  }

  private getNestingLevel(): { level: number; icons: number } {
    let level = 0;
    let icons = 0;

    let parent = this.host.parentNode;

    if (!this.hasChildItems() && (parent as HTMLGroupuiBurgerMenuItemElement).treeLayout) {
      icons++;
    }

    while (parent != null) {
      if (parent.nodeName === 'GROUPUI-BURGER-MENU') {
        break;
      }
      if (parent.nodeName === 'GROUPUI-BURGER-MENU-ITEM') {
        level++;
        const parentItem = parent as HTMLGroupuiBurgerMenuItemElement;
        if (parentItem.icon) {
          icons++;
        }
      }
      parent = parent.parentNode;
    }

    return { level, icons };
  }

  private hasChildItems(): boolean {
    let hasItemChild = false;
    this.host.childNodes.forEach((child) => {
      if (child.nodeName === 'GROUPUI-BURGER-MENU-ITEM' || child.nodeName === 'GROUPUI-BURGER-MENU-CATEGORY') {
        hasItemChild = true;
      }
    });
    return hasItemChild;
  }

  render() {
    return (
      <Host>
        <slot></slot>
      </Host>
    );
  }
}
